    disclaimerText: 'Qabiyyeen kun barnoota qofaaf. Gaaffiin amantaa ulamaa\'ota dandeettii qabanii mirkaneessuu qaba. AWA fatwaa ykn murtii amantaa ofii-isaaf ta\'e hin kennu.',
