    tip3Title: 'ጽቡቕ ምፍላጥ',
    tip3Text: 'ኣብ ግዜ ወርሓዊ ዓደት ዝቋረጽ ጾም ዝፍለጥ ልዝብ እዩ፣ ካብ ሃይማኖታዊ ተግባርካ ዕረፍቲ ኣይኮነን። እዚ ግዜ ብዝተፈለየ ምሕላፍ፣ መዓልታትካ ምክታልን ምስ ዝተጠራጠርካ መምርሒ ምሕታትን ኩሉ ረመዳን ብሰላም ንምሕላፍ ይሕግዙ።',
