    disclaimerText: 'Ibi bikubiyemo ni iby’inyigisho gusa. Ibibazo by’idini bigomba kwemezwa n’abahanga babifitiye ubushobozi. AWA ntitanga fatwa cyangwa ibyemezo by’idini byihariye.',
