    section1Body1: 'Mu gihe cy’imihango yawe, gusiba ntibitegetswe: iki gihe gishyira umugore mu mimerere aho ibikorwa byinshi byo gusenga, harimo no gusiba, bihagarikwa by’agateganyo. Uku guhagarikwa kwemerwa nk’impuhwe, ntabwo ari ukubuzwa cyangwa igihano.',
    section1Body2: 'Guhagarika gusiba mu gihe cy’imihango yawe ntibivuze kuva mu migenzo y’idini. Birahagarikwa igihe gito gusa, hanyuma bigasubukurwa nk’uko bisanzwe imihango irangiye, nta gikorwa cy’ukwemera gitakaye. Iminsi itasibwe izishyurwa nyuma (qadaa), hanze ya Ramadan.',
    tip1Title: 'Ni byiza kubimenya',
