    tip1Title: 'Ọ dị mma ịmara',
    tip1Text: 'A pụkwara ibi nkwụsị a dị ka oge dị iche n\'ime ọnwa, ebe ndụ mmụọ na-aga n\'ihu na-egosi onwe ya n\'ụzọ ndị ọzọ, n\'enweghị sawm.',
    note1Title: 'Biko cheta',
