    section2Body: 'Ịghara ibu ọnụ apụtaghị ịpụ n\'ọnwa Ramadan. Ọtụtụ ụdị ndụ mmụọ ka dị n\'aka ma na-enye gị ohere ịga n\'ihu ibi oge a nke ọma.',
