    section3Body: 'Idebe ụbọchị nsọ ọnwa gị n\'oge Ramadan na-eme ka o dịrị gị mfe ịgbakọ ọnụ ọgụgụ ụbọchị a ga-akwụghachi (qadaa) ma e mesịa, ma na-egbochi ịdabere naanị n\'ncheta mgbe ọnwa gasịrị.',
