    note2Title: 'Biko cheta',
    note2Text: 'Usoro ziri ezi nke ịkwụghachi ụbọchị ndị e hapụrụ (oge, ọnọdụ pụrụ iche dị ka ime ma ọ bụ inyere nwa ara) nwere ike ịdị iche dabere n\'ụlọ akwụkwọ ikpe okpukpe. Maka ọnọdụ ọ bụla pụrụ iche ma ọ bụ siri ike, echiche onye ọkà mmụta nwere ikike ka bụ ntụaka.',
