    note2Text: 'Imigomo ethile yokwenza kabusha izinsuku ezingaziliwe (isikhathi, izimo ezikhethekile njengokukhulelwa noma ukuncelisa) ingahluka ngokuya ngesikole se-fiqh. Ngesimo esithile noma esinzima, umbono wesazi esifanelekile uhlala uyisethenjwa.',
