    section1Body2: 'Ukumisa ukuzila ngexesha lenyanga akuthethi ukuya kude nonqulo lwakho. Kumiswa nje okwexeshana elimiselweyo, emva koko liqalisa kwakhona ngokuqhelekileyo xa ixesha lenyanga liphela, ngaphandle kokulahleka kwesenzo sokholo. Iintsuku ezingazilwanga ziza kuhlawulwa kamva (qadaa), ngaphandle kwe-Ramadan.',
