    section1Body1: 'በወር አበባሽ ጊዜ መጾም አይጠበቅብሽም፦ ይህ ጊዜ ሴትን ጾምን ጨምሮ ብዙ የአምልኮ ድርጊቶች ለጊዜው በሚታገዱበት ሁኔታ ውስጥ ያስገባታል። ይህ እገዳ እንደ እፎይታ እንጂ እንደ ክልከላ ወይም ቅጣት አይታወቅም።',
    section1Body2: 'በወር አበባሽ ጊዜ ጾምን ማቋረጥ ከሃይማኖታዊ ተግባርሽ መራቅ ማለት አይደለም። ለተወሰነ ጊዜ ብቻ ይቆማል፣ ከዚያ የወር አበባሽ ሲያበቃ በተለምዶ ይቀጥላል፣ ምንም የእምነት ድርጊት ሳይጠፋ። ያልተጾሙት ቀናት ከረመዳን ውጭ በኋላ ይካሳሉ (ቀዷእ)።',
