    section1Body2: 'Η αναστολή της νηστείας κατά την περίοδό σου δεν σημαίνει απομάκρυνση από τη θρησκευτική σου πρακτική. Απλώς τίθεται σε παύση για περιορισμένο χρόνο και στη συνέχεια ξαναρχίζει κανονικά μόλις τελειώσει η περίοδός σου, χωρίς να χάνεται καμία πράξη πίστης. Οι ημέρες που δεν νήστεψες θα αναπληρωθούν αργότερα (καδά), εκτός Ραμαζανιού.',
    tip1Title: 'Καλό είναι να γνωρίζεις',
    tip1Text: 'Αυτή η παύση μπορεί επίσης να βιωθεί ως ένας διαφορετικός χρόνος μέσα στον μήνα, όπου η πνευματικότητα συνεχίζει να εκφράζεται με άλλους τρόπους, χωρίς νηστεία.',
    note1Title: 'Σημείωση',
    note1Text: 'Αυτή η κατάσταση δεν πρέπει να βιώνεται με ενοχές: αποτελεί μέρος του φυσικού κύκλου του σώματος και λαμβάνεται υπόψη από την ίδια τη θρησκευτική παράδοση.',
    section2Body: 'Το να μη νηστεύεις δεν σημαίνει ότι αποκόπτεσαι από τον μήνα του Ραμαζανιού. Πολλές μορφές πνευματικότητας παραμένουν προσβάσιμες και σου επιτρέπουν να συνεχίζεις να βιώνεις πλήρως αυτή την περίοδο.',
    spiritualActs: [
      'Ντικρ (ανάμνηση του Θεού)',
      'Ντουά (δεήσεις)',
      'Ακρόαση θρησκευτικού περιεχομένου',
      'Ανάγνωση εκπαιδευτικού περιεχομένου',
      'Φιλανθρωπία και πράξεις καλοσύνης',
      'Βοήθεια στην προετοιμασία του ιφτάρ',
      'Χρόνος για προσωπικό στοχασμό',
      'Διατήρηση μιας πνευματικής ρουτίνας',
    ],
    tip2Title: 'Καλό είναι να γνωρίζεις',
    tip2Text: 'Αυτές οι μικρές χειρονομίες, ακόμη και απλές, σε βοηθούν να παραμένεις πλήρως συνδεδεμένη με το πνεύμα του μήνα, όποια κι αν είναι η κατάστασή σου.',
    section3Body: 'Η παρακολούθηση των ημερών της περιόδου σου κατά το Ραμαζάνι διευκολύνει στη συνέχεια τον υπολογισμό του αριθμού των ημερών προς αναπλήρωση (καδά) και αποφεύγει να βασίζεσαι στη μνήμη μόλις τελειώσει ο μήνας.',
