    visualTitle: 'Απλοποιημένη παρακολούθηση',
    visualText: 'Το AWA μπορεί να σε βοηθήσει να παρακολουθείς τον κύκλο σου σε όλη τη διάρκεια του Ραμαζανιού, ώστε να βρίσκεις εύκολα αυτές τις πληροφορίες αργότερα.',
    note2Title: 'Σημείωση',
    note2Text: 'Οι ακριβείς όροι αναπλήρωσης των ημερών που χάθηκαν (χρονισμός, ειδικές περιπτώσεις όπως εγκυμοσύνη ή θηλασμός) μπορεί να διαφέρουν ανάλογα με τη νομική σχολή. Για κάθε ειδική ή σύνθετη περίπτωση, η γνώμη ενός ειδικού θεολόγου παραμένει η αναφορά.',
    tip3Title: 'Καλό είναι να γνωρίζεις',
