    section1Body1: 'மாதவிடாயின்போது, நோன்பு கடமையல்ல: இந்தக் காலம் ஒரு பெண்ணை, நோன்பு உட்பட பல வணக்கங்கள் தற்காலிகமாக நிறுத்தப்படும் நிலையில் வைக்கிறது. இந்த நிறுத்தம் ஒரு சலுகையாக அங்கீகரிக்கப்படுகிறது, தடையாகவோ தண்டனையாகவோ அல்ல.',
