    section1Body1: 'માસિક દરમિયાન રોઝા રાખવા જરૂરી નથી: આ સમય સ્ત્રીને એવી અવસ્થામાં મૂકે છે જેમાં રોઝા સહિત ઇબાદતનાં ઘણાં કાર્યો અસ્થાયી રૂપે સ્થગિત રહે છે. આ સ્થગિતતા રાહત તરીકે માન્ય છે, મનાઈ કે સજા તરીકે નહીં.',
    section1Body2: 'માસિક દરમિયાન રોઝા સ્થગિત કરવાનો અર્થ ધાર્મિક આચરણથી દૂર થવું એવો નથી. તે ફક્ત મર્યાદિત સમય માટે થોભે છે, અને માસિક પૂરું થયા પછી સામાન્ય રીતે ફરી શરૂ થાય છે, શ્રદ્ધાનું કોઈ કાર્ય ગુમાવ્યા વિના. ન રખાયેલા રોઝાના દિવસોની કઝા રમઝાન પછી કરવામાં આવશે.',
    tip1Title: 'જાણવા જેવું',
    tip1Text: 'આ વિરામને મહિનાની અંદરના એક અલગ પ્રકારના સમય તરીકે પણ જીવી શકાય, જ્યાં રોઝા વિના પણ આધ્યાત્મિકતા બીજી રીતે વ્યક્ત થતી રહે છે.',
    note1Title: 'કૃપા કરીને નોંધો',
    note1Text: 'આ પરિસ્થિતિને અપરાધભાવ સાથે જીવવી ન જોઈએ: તે શરીરના કુદરતી ચક્રનો ભાગ છે અને ધાર્મિક પરંપરાએ પોતે તેને ધ્યાનમાં લીધી છે.',
    section2Body: 'રોઝા ન રાખવાનો અર્થ રમઝાન મહિનાથી કપાઈ જવું એવો નથી. આધ્યાત્મિકતાના ઘણા પ્રકારો શક્ય રહે છે અને તમને આ સમયને પૂરેપૂરો જીવવા દે છે.',
