    section3Body: 'રમઝાન દરમિયાન તમારા માસિકના દિવસોનો હિસાબ રાખવાથી પછીથી કઝાના દિવસોની સંખ્યા ગણવી સરળ બને છે, અને મહિનો પૂરો થયા પછી યાદશક્તિ પર આધાર રાખવો પડતો નથી.',
