    disclaimerTitle: 'ਜ਼ਰੂਰੀ ਜਾਣਕਾਰੀ',
    disclaimerText: 'ਇਹ ਸਮੱਗਰੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਿੱਖਿਆ ਲਈ ਹੈ। ਧਾਰਮਿਕ ਸਵਾਲਾਂ ਦੀ ਪੁਸ਼ਟੀ ਯੋਗ ਵਿਦਵਾਨਾਂ ਤੋਂ ਕਰਵਾਉਣੀ ਚਾਹੀਦੀ ਹੈ। AWA ਫ਼ਤਵੇ ਜਾਂ ਨਿੱਜੀ ਧਾਰਮਿਕ ਹੁਕਮ ਜਾਰੀ ਨਹੀਂ ਕਰਦਾ।',
