    section1Body1: 'ਮਾਹਵਾਰੀ ਦੌਰਾਨ ਰੋਜ਼ਾ ਰੱਖਣਾ ਜ਼ਰੂਰੀ ਨਹੀਂ ਹੈ: ਇਹ ਸਮਾਂ ਔਰਤ ਨੂੰ ਅਜਿਹੀ ਹਾਲਤ ਵਿੱਚ ਰੱਖਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਰੋਜ਼ੇ ਸਮੇਤ ਕਈ ਇਬਾਦਤਾਂ ਅਸਥਾਈ ਤੌਰ ਉੱਤੇ ਮੁਅੱਤਲ ਰਹਿੰਦੀਆਂ ਹਨ। ਇਸ ਮੁਅੱਤਲੀ ਨੂੰ ਇੱਕ ਰਾਹਤ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ, ਨਾ ਕਿ ਮਨਾਹੀ ਜਾਂ ਸਜ਼ਾ।',
    section1Body2: 'ਮਾਹਵਾਰੀ ਦੌਰਾਨ ਰੋਜ਼ਾ ਮੁਅੱਤਲ ਕਰਨ ਦਾ ਮਤਲਬ ਆਪਣੇ ਧਾਰਮਿਕ ਅਮਲ ਤੋਂ ਪਿੱਛੇ ਹਟਣਾ ਨਹੀਂ ਹੈ। ਇਹ ਸਿਰਫ਼ ਸੀਮਤ ਸਮੇਂ ਲਈ ਰੁਕਿਆ ਹੁੰਦਾ ਹੈ, ਫਿਰ ਮਾਹਵਾਰੀ ਖ਼ਤਮ ਹੋਣ ਉੱਤੇ ਆਮ ਵਾਂਗ ਮੁੜ ਸ਼ੁਰੂ ਹੋ ਜਾਂਦਾ ਹੈ, ਬਿਨਾਂ ਕਿਸੇ ਈਮਾਨ ਦੇ ਅਮਲ ਦੇ ਗੁਆਏ। ਨਾ ਰੱਖੇ ਗਏ ਦਿਨਾਂ ਦੀ ਬਾਅਦ ਵਿੱਚ, ਰਮਜ਼ਾਨ ਤੋਂ ਬਾਹਰ, ਕਜ਼ਾ ਕੀਤੀ ਜਾਵੇਗੀ।',
    tip1Title: 'ਜਾਣਨ ਯੋਗ',
    tip1Text: 'ਇਸ ਵਿਰਾਮ ਨੂੰ ਮਹੀਨੇ ਦੇ ਅੰਦਰ ਇੱਕ ਵੱਖਰੇ ਕਿਸਮ ਦੇ ਸਮੇਂ ਵਜੋਂ ਵੀ ਜਿਉਇਆ ਜਾ ਸਕਦਾ ਹੈ, ਜਿੱਥੇ ਰੋਜ਼ੇ ਤੋਂ ਬਿਨਾਂ ਵੀ ਰੂਹਾਨੀਅਤ ਹੋਰ ਤਰੀਕਿਆਂ ਨਾਲ ਪ੍ਰਗਟ ਹੁੰਦੀ ਰਹਿੰਦੀ ਹੈ।',
