    note1Text: 'ਇਸ ਹਾਲਤ ਨੂੰ ਦੋਸ਼-ਭਾਵ ਨਾਲ ਨਹੀਂ ਜਿਉਣਾ ਚਾਹੀਦਾ: ਇਹ ਸਰੀਰ ਦੇ ਕੁਦਰਤੀ ਚੱਕਰ ਦਾ ਹਿੱਸਾ ਹੈ ਅਤੇ ਧਾਰਮਿਕ ਰਵਾਇਤ ਨੇ ਖ਼ੁਦ ਇਸ ਦਾ ਲਿਹਾਜ਼ ਰੱਖਿਆ ਹੈ।',
    section2Body: 'ਰੋਜ਼ਾ ਨਾ ਰੱਖਣ ਦਾ ਮਤਲਬ ਰਮਜ਼ਾਨ ਦੇ ਮਹੀਨੇ ਤੋਂ ਕੱਟੇ ਜਾਣਾ ਨਹੀਂ ਹੈ। ਰੂਹਾਨੀਅਤ ਦੇ ਕਈ ਰੂਪ ਪਹੁੰਚ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਤੁਹਾਨੂੰ ਇਸ ਸਮੇਂ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜਿਉਂਦੇ ਰਹਿਣ ਦਿੰਦੇ ਹਨ।',
