    tip2Title: 'ਜਾਣਨ ਯੋਗ',
    tip2Text: 'ਇਹ ਛੋਟੇ-ਛੋਟੇ ਕੰਮ, ਭਾਵੇਂ ਸਾਧਾਰਨ ਹੀ ਹੋਣ, ਤੁਹਾਨੂੰ ਮਹੀਨੇ ਦੀ ਰੂਹ ਨਾਲ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜੁੜੇ ਰਹਿਣ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਨ, ਤੁਹਾਡੇ ਹਾਲਾਤ ਜੋ ਵੀ ਹੋਣ।',
    section3Body: 'ਰਮਜ਼ਾਨ ਦੌਰਾਨ ਆਪਣੀ ਮਾਹਵਾਰੀ ਦੇ ਦਿਨਾਂ ਦਾ ਹਿਸਾਬ ਰੱਖਣ ਨਾਲ ਬਾਅਦ ਵਿੱਚ ਕਜ਼ਾ ਕਰਨ ਵਾਲੇ ਦਿਨਾਂ ਦੀ ਗਿਣਤੀ ਕੱਢਣੀ ਸੌਖੀ ਹੋ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਮਹੀਨਾ ਲੰਘ ਜਾਣ ਤੋਂ ਬਾਅਦ ਯਾਦਦਾਸ਼ਤ ਉੱਤੇ ਨਿਰਭਰ ਨਹੀਂ ਹੋਣਾ ਪੈਂਦਾ।',
